+
+QString SessionManagement::formatShutdownInhibitors(const QList<ShutdownInhibitor> &inhibitors)
+{
+    if (inhibitors.isEmpty()) {
+        return {};
+    }
+
+    if (inhibitors.size() == 1) {
+        const auto &inhibitor = inhibitors.constFirst();
+        if (inhibitor.why.isEmpty()) {
+            return i18nc("@info:status %1 is an application name", "%1 is currently blocking shutdown.", inhibitor.who);
+        }
+        return i18nc("@info:status %1 is an application name, %2 is the reason it gives for blocking shutdown",
+                     "%1 is currently blocking shutdown: %2",
+                     inhibitor.who,
+                     inhibitor.why);
+    }
+
+    QStringList applications;
+    applications.reserve(inhibitors.size());
+    for (const auto &inhibitor : inhibitors) {
+        applications.append(
+            inhibitor.why.isEmpty()
+                ? inhibitor.who
+                : i18nc("@item %1 is an application name, %2 is the reason it gives for blocking shutdown", "%1: %2", inhibitor.who, inhibitor.why));
+    }
+    return i18nc("@info:status %1 is a list of applications and their reasons, one per line",
+                 "The following applications are currently blocking shutdown:\n%1",
+                 applications.join(u'\n'));
+}
+
