diff --git a/libkworkspace/sessionmanagementbackend.cpp b/libkworkspace/sessionmanagementbackend.cpp
index d0742bfb9a..f0d24b557a 100644
--- a/libkworkspace/sessionmanagementbackend.cpp
+++ b/libkworkspace/sessionmanagementbackend.cpp
@@ -12,15 +12,98 @@

 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
+#include <QDBusMessage>
+#include <QDBusMetaType>
 #include <QDBusPendingCallWatcher>
+#include <QDBusVariant>
+#include <QRegularExpression>
+#include <QTimer>

 #include <KConfigGroup>
+#include <algorithm>
 #include <iostream>
+#include <iterator>
+#include <memory>
+
+#include <unistd.h>

 #include "login1_manager_interface.h"

+using namespace Qt::StringLiterals;
+using namespace std::chrono_literals;
+
 static SessionBackend *s_backend = nullptr;

+namespace
+{
+enum class CanReply {
+    Yes,
+    Challenge,
+    No,
+    NotApplicable,
+    InhibitorBlocked,
+};
+
+CanReply parseCanReply(const QString &reply)
+{
+    if (reply == u"yes") {
+        return CanReply::Yes;
+    }
+    if (reply == u"challenge") {
+        return CanReply::Challenge;
+    }
+    if (reply == u"na") {
+        return CanReply::NotApplicable;
+    }
+    if (reply == u"inhibited" || reply == u"inhibitor-blocked" || reply == u"challenge-inhibitor-blocked") {
+        return CanReply::InhibitorBlocked;
+    }
+    return CanReply::No;
+}
+
+bool isShutdownLock(const Inhibitor &inhibitor)
+{
+    return inhibitor.what.split(u':').contains(u"shutdown");
+}
+
+bool isOwnBlockLock(const Inhibitor &inhibitor, uint uid)
+{
+    return isShutdownLock(inhibitor) && inhibitor.mode == u"block" && inhibitor.userId == uid;
+}
+
+InhibitorList blockingShutdownInhibitors(const InhibitorList &inhibitors, uint uid, bool blockLocksApplyToOwner)
+{
+    InhibitorList result;
+    std::ranges::copy_if(inhibitors, std::back_inserter(result), [uid, blockLocksApplyToOwner](const Inhibitor &inhibitor) {
+        if (!isShutdownLock(inhibitor)) {
+            return false;
+        }
+        if (inhibitor.userId == uid) {
+            return blockLocksApplyToOwner && inhibitor.mode == u"block";
+        }
+        return inhibitor.mode == u"block" || inhibitor.mode == u"block-weak";
+    });
+    return result;
+}
+
+QList<ShutdownInhibitor> toShutdownInhibitors(const InhibitorList &inhibitors)
+{
+    QList<ShutdownInhibitor> result;
+    result.reserve(inhibitors.size());
+    for (const Inhibitor &inhibitor : inhibitors) {
+        result.append({.who = inhibitor.who, .why = inhibitor.why});
+    }
+    return result;
+}
+
+void warnOnError(const QDBusPendingCall &call, const char *what)
+{
+    if (call.isError()) {
+        qWarning() << what << call.error().name() << call.error().message();
+    }
+}
+} // namespace
+
 SessionBackend *SessionBackend::self()
 {
     static QMutex mutex;
@@ -56,6 +139,21 @@ bool SessionBackend::canSwitchUser() const
     return false;
 }

+void SessionBackend::checkInhibition(PowerAction, QObject *context, const std::function<void(const ShutdownInhibition &)> &callback)
+{
