+}
+
 DummySessionBackend::DummySessionBackend()
 {
     qCritical() << "Could not load a session backend. Session management operations such as shutdown will not be operational. This is a setup issue.";
@@ -109,31 +207,12 @@ LogindSessionBackend::LogindSessionBackend()
         watcher->deleteLater();
         m_pendingJobs--;
         QDBusPendingReply<QString> reply = *watcher;
-        if (reply.isError()) {
-            *argToUpdate = false;
-        } else {
-            // both "yes" and "challenge" will show up in the UI
-            // also accept "inhibited" for now, TODO expose this more fine-grained and indicate in the UI that the action is inhibited (and why)
-            const QString value = reply.value();
-            *argToUpdate = false;
-            if (value == QLatin1String("yes") || value == QLatin1String("challenge") || value == QLatin1String("inhibited")
-                || value == QLatin1String("inhibited-blocked") || value == QLatin1String("challenge-inhibitor-blocked")) {
-                *argToUpdate = true;
-            }
-        }
-
-        if (m_pendingJobs == 0) {
-            m_state = SessionManagement::State::Ready;
-            Q_EMIT stateChanged();
-            Q_EMIT canShutdownChanged();
-            Q_EMIT canRebootChanged();
-            Q_EMIT canSuspendChanged();
-            Q_EMIT canHibernateChanged();
-            Q_EMIT canSuspendThenHibernateChanged();
-        }
+        const CanReply value = reply.isError() ? CanReply::No : parseCanReply(reply.value());
+        *argToUpdate = value == CanReply::Yes || value == CanReply::Challenge || value == CanReply::InhibitorBlocked;
+        markReadyIfLoaded();
     };

-    m_pendingJobs = 5;
+    m_pendingJobs = 6;
     {
         auto watcher = new QDBusPendingCallWatcher(m_login1->CanPowerOff(), this);
         connect(watcher, &QDBusPendingCallWatcher::finished, this, std::bind(propLoaded, std::placeholders::_1, &m_canShutdown));
@@ -166,6 +245,154 @@ LogindSessionBackend::LogindSessionBackend()
             Q_EMIT resumingFromSuspend();
         }
     });
+
+    qDBusRegisterMetaType<Inhibitor>();
+    qDBusRegisterMetaType<InhibitorList>();
+
+    QDBusConnection::systemBus().connect(m_login1->service(),
+                                         m_login1->path(),
+                                         QStringLiteral("org.freedesktop.DBus.Properties"),
+                                         QStringLiteral("PropertiesChanged"),
+                                         this,
+                                         SLOT(onLogin1PropertiesChanged(QString, QVariantMap, QStringList)));
+    updateShutdownInhibitors();
