+}
+
+void LogindSessionBackend::markReadyIfLoaded()
+{
+    if (m_state == SessionManagement::State::Ready || m_pendingJobs > 0 || !m_shutdownInhibitorsLoaded) {
+        return;
+    }
+    m_state = SessionManagement::State::Ready;
+    Q_EMIT stateChanged();
+    Q_EMIT canShutdownChanged();
+    Q_EMIT canRebootChanged();
+    Q_EMIT canSuspendChanged();
+    Q_EMIT canHibernateChanged();
+    Q_EMIT canSuspendThenHibernateChanged();
+}
+
+void LogindSessionBackend::onLogin1PropertiesChanged(const QString &interface, const QVariantMap &changed, const QStringList &invalidated)
+{
+    if (interface != m_login1->interface()) {
+        return;
+    }
+    for (const QString &property : {u"BlockInhibited"_s, u"BlockWeakInhibited"_s}) {
+        if (changed.contains(property) || invalidated.contains(property)) {
+            updateShutdownInhibitors();
+            return;
+        }
+    }
+}
+
+// Before systemd 257, logind ignores "block" inhibitors held by the user requesting the shutdown.
+// Since 257 they block their owner too, and "block-weak" keeps the old behavior.
+void LogindSessionBackend::queryBlockLocksApplyToOwner(QObject *context, const std::function<void(bool)> &callback)
+{
+    if (m_blockLocksApplyToOwner.has_value()) {
+        callback(*m_blockLocksApplyToOwner);
+        return;
+    }
+
+    QDBusMessage message =
+        QDBusMessage::createMethodCall(u"org.freedesktop.systemd1"_s, u"/org/freedesktop/systemd1"_s, u"org.freedesktop.DBus.Properties"_s, u"Get"_s);
+    message << u"org.freedesktop.systemd1.Manager"_s << u"Version"_s;
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message), context);
+    connect(watcher, &QDBusPendingCallWatcher::finished, context, [this, callback](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<QDBusVariant> reply = *watcher;
+        warnOnError(reply, "Failed to query the systemd version");
+        static const QRegularExpression majorVersionExpr(u"^(\\d+)"_s);
+        const QRegularExpressionMatch match = majorVersionExpr.match(reply.isError() ? QString() : reply.value().variant().toString());
+        m_blockLocksApplyToOwner = match.hasMatch() && match.captured(1).toInt() >= 257;
+        callback(*m_blockLocksApplyToOwner);
+    });
+}
+
+void LogindSessionBackend::checkInhibition(PowerAction action, QObject *context, const std::function<void(const ShutdownInhibition &)> &callback)
+{
+    auto watcher = new QDBusPendingCallWatcher(action == PowerAction::Reboot ? m_login1->CanReboot() : m_login1->CanPowerOff(), context);
+    connect(watcher, &QDBusPendingCallWatcher::finished, context, [this, context, callback](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<QString> canReply = *watcher;
+        warnOnError(canReply, "Failed to check whether the power action is allowed");
+        if (canReply.isError()) {
+            callback({});
+            return;
+        }
+
+        const CanReply value = parseCanReply(canReply.value());
+        if (value == CanReply::Yes || value == CanReply::NotApplicable) {
+            callback({});
+            return;
+        }
+
+        const bool blocked = value == CanReply::InhibitorBlocked;
+        auto listWatcher = new QDBusPendingCallWatcher(m_login1->ListInhibitors(), context);
+        connect(listWatcher, &QDBusPendingCallWatcher::finished, context, [this, context, blocked, callback](QDBusPendingCallWatcher *listWatcher) {
+            listWatcher->deleteLater();
+            const QDBusPendingReply<InhibitorList> listReply = *listWatcher;
+            warnOnError(listReply, "Failed to list inhibitors");
+            if (listReply.isError()) {
+                callback({.inhibited = blocked});
+                return;
+            }
+
+            const InhibitorList allInhibitors = listReply.value();
+            const uint uid = getuid();
+            auto finish = [callback, blocked, allInhibitors, uid](bool blockLocksApplyToOwner) {
+                const InhibitorList inhibitors = blockingShutdownInhibitors(allInhibitors, uid, blockLocksApplyToOwner);
+                callback({.inhibited = blocked || !inhibitors.isEmpty(), .inhibitors = toShutdownInhibitors(inhibitors)});
+            };
+
+            if (blocked) {
+                finish(true);
+            } else if (std::ranges::any_of(allInhibitors, [uid](const Inhibitor &inhibitor) {
+                           return isOwnBlockLock(inhibitor, uid);
+                       })) {
+                queryBlockLocksApplyToOwner(context, finish);
+            } else {
+                finish(false);
+            }
+        });
+    });
+}
+
+void LogindSessionBackend::updateShutdownInhibitors()
+{
+    const quint64 generation = ++m_shutdownInhibitorsGeneration;
+    auto results = std::make_shared<QList<ShutdownInhibition>>();
+    auto collect = [this, generation, results](const ShutdownInhibition &inhibition) {
+        results->append(inhibition);
+        if (results->size() < 2 || generation != m_shutdownInhibitorsGeneration) {
+            return;
+        }
+
+        const auto inhibited = std::ranges::find(*results, true, &ShutdownInhibition::inhibited);
+        const QList<ShutdownInhibitor> inhibitors = inhibited == results->cend() ? QList<ShutdownInhibitor>() : inhibited->inhibitors;
+        if (m_shutdownInhibitors != inhibitors) {
+            m_shutdownInhibitors = inhibitors;
+            Q_EMIT shutdownInhibitorsChanged();
+        }
+        if (!m_shutdownInhibitorsLoaded) {
+            m_shutdownInhibitorsLoaded = true;
+            markReadyIfLoaded();
+        }
+    };
+    checkInhibition(PowerAction::PowerOff, this, collect);
+    checkInhibition(PowerAction::Reboot, this, collect);
+}
