+void Shutdown::notifyShutdownInhibited(ShutdownType shutdownType, const ShutdownInhibition &inhibition)
+{
+    const QString title =
+        shutdownType == ShutdownTypeReboot ? i18nc("@title:notification", "Cannot Restart") : i18nc("@title:notification", "Cannot Shut Down");
+    const QString text = inhibition.inhibitors.isEmpty() ? i18nc("@info:status", "An unknown application is currently preventing it.")
+                                                         : SessionManagement::formatShutdownInhibitors(inhibition.inhibitors);
+
+    if (m_inhibitedNotification) {
+        disconnect(m_inhibitedNotification, nullptr, this, nullptr);
+        m_inhibitedNotification->close();
+    }
+
+    m_inhibitedNotification = new KNotification(QStringLiteral("cancellogout"));
+    m_inhibitedNotification->setComponentName(QStringLiteral("plasma_workspace"));
+    m_inhibitedNotification->setTitle(title);
+    m_inhibitedNotification->setText(text.toHtmlEscaped());
+    m_inhibitedNotification->setIconName(QStringLiteral("system-shutdown"));
+    m_inhibitedNotification->setUrgency(KNotification::CriticalUrgency);
+    connect(m_inhibitedNotification, &KNotification::closed, this, [this]() {
+        if (m_shutdownType == ShutdownTypeNone) {
+            qApp->quit();
+        }
+    });
+    m_inhibitedNotification->sendEvent();
